package com.meridiantrust.sentinel;
import com.meridiantrust.sentinel.api.Dto.TxIn; import com.meridiantrust.sentinel.repo.Repositories.Alerts; import com.meridiantrust.sentinel.service.SentinelService; import org.junit.jupiter.api.Test; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.beans.factory.annotation.Autowired; import java.math.BigDecimal; import java.time.Instant; import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"SENTINEL_API_USERNAME=test","SENTINEL_API_PASSWORD=test"}) class SentinelSmokeTest { @Autowired SentinelService service; @Autowired Alerts alerts; @Test void createsAggregatedStructuringAlert(){Instant now=Instant.now();for(int i=1;i<=3;i++)service.transaction(new TxIn("TEST-STRUCT-"+i,"IN-DEMO-1001",new BigDecimal("9500"),"INR","CREDIT","Cash","IN","BRANCH",now.plusSeconds(i)));assertTrue(alerts.findAll().stream().anyMatch(a->a.ruleCode.equals("STRUCTURING")));} }
